// The parts of web/privacy.html that depend on the configuration, generated by configure.mjs so the page always
// says what the site really does: statistics off/on, survey absent/present, publisher and contact.

const esc = (s) => String(s).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");

export function statsBlock(cfg) {
  if (!cfg.goatcounter) {
    return `  <h2>Mesure d'audience : pas encore active</h2>
  <p>Aujourd'hui, CostDiff n'envoie aucune statistique : aucune requête n'est faite vers GoatCounter ni vers un autre service de mesure. Si la mesure est activée, elle utilisera <a href="https://www.goatcounter.com/help/privacy">GoatCounter</a>, un service sans cookie hébergé dans l'Union européenne, et cette page sera mise à jour avant l'activation.</p>`;
  }
  return `  <h2>Mesure d'audience (GoatCounter)</h2>
  <p>Pour savoir si CostDiff est utile, nous comptons les visites avec <a href="https://www.goatcounter.com/help/privacy">GoatCounter</a>, un service de statistiques sans cookie hébergé dans l'Union européenne (serveurs Hetzner en Finlande et en Allemagne).</p>
  <p>Ce qui est envoyé, et rien d'autre :</p>
  <ul>
    <li>la page vue (présentation, outil, Pro, confidentialité), sans les paramètres de l'adresse ;</li>
    <li>le site d'où vous venez (par exemple « www.google.com » ou le nom d'un forum), sans la page ni les termes de recherche ;</li>
    <li>les étiquettes de campagne éventuelles d'un lien (par exemple <code>utm_source=forum</code>) ;</li>
    <li>des événements de nom fixe : « fichier personnel lu », « fichier refusé », « exemples chargés », « comparaison terminée », « rapport exporté », « clic vers la page Pro », « clic vers le questionnaire », « clic sur le contact » (avec son motif : question, problème, suggestion, Pro, démonstration), en distinguant seulement vos fichiers des fichiers d'exemple.</li>
  </ul>
  <p>Comme tout serveur, GoatCounter reçoit votre adresse IP et l'identification de votre navigateur. D'après sa politique de confidentialité, il ne les conserve pas : il en déduit le pays, le navigateur et le système, et ne garde que des totaux ; un identifiant anonyme et temporaire, effacé après quelques heures, sert seulement à ne pas compter deux fois la même visite (l'enregistrement des vues individuelles est désactivé pour CostDiff). Aucun cookie et aucun stockage dans votre navigateur ne servent à la mesure. Fondement : l'intérêt légitime du responsable à savoir si l'outil est utilisé.</p>
  <p>Vous pouvez désactiver la mesure pour votre navigateur en ouvrant <a href="index.html#nostats">cette adresse</a> (et la réactiver avec <a href="index.html#stats">celle-ci</a>). Ce choix est gardé dans le stockage local de votre navigateur.</p>`;
}

export function formBlock(cfg) {
  if (!cfg.form) return "";
  return `  <h2>Questionnaire sur la version Pro (Tally)</h2>
  <p>Le questionnaire de la page <a href="pro.html">Pro</a> est facultatif et hébergé par <a href="https://tally.so/help/privacy-policy">Tally</a> (Tally BV, Belgique, données dans l'Union européenne). Vos réponses servent uniquement à décider quoi construire dans CostDiff. L'adresse e-mail est facultative ; si vous la donnez et cochez la case prévue, elle sert uniquement à vous recontacter au sujet de CostDiff Pro (trois messages au plus, désinscription à tout moment par simple réponse). Elle n'est ni vendue ni partagée.</p>
  <p>Fondement : votre consentement, que vous pouvez retirer à tout moment. Conservation : 12 mois après votre réponse, puis suppression.</p>
  <p><strong>N'envoyez jamais de tarif fournisseur ni de prix confidentiels dans le questionnaire.</strong></p>`;
}

export function publisherBlock(cfg) {
  const issues = `<a href="https://github.com/lukasdevahive/costdiff/issues">issues du dépôt GitHub</a> (publiques : n'y mettez pas vos tarifs)`;
  if (!cfg.controller) {
    return `  <h2>Éditeur et contact</h2>
  <p>CostDiff est publié par le titulaire du compte GitHub <a href="https://github.com/lukasdevahive">lukasdevahive</a>, à titre personnel (aucune société). L'éditeur ne traite lui-même aucune donnée personnelle : il n'y a ni compte, ni mesure d'audience, ni formulaire.</p>
  <p>Contact : ${cfg.contact ? `<a href="mailto:${esc(cfg.contact)}" data-stat="contact-click">${esc(cfg.contact)}</a>, ou les ${issues}` : issues}.</p>`;
  }
  return `  <h2>Responsable du traitement et contact</h2>
  <p>Responsable du traitement : ${esc(cfg.controller)}, à titre personnel (aucune société). Contact : <a href="mailto:${esc(cfg.contact)}" data-stat="contact-click">${esc(cfg.contact)}</a>.</p>
  <p>Cette messagerie est hébergée par Google (Gmail), qui peut traiter les messages hors de l'Union européenne selon ses propres garanties (clauses contractuelles types). Les messages envoyés à cette adresse servent uniquement à vous répondre et sont supprimés au plus tard 12 mois après le dernier échange. Vous pouvez demander l'accès, la correction ou la suppression de vos données à cette adresse, et introduire une réclamation auprès de l'Autorité de protection des données (Belgique). Questions techniques : ${issues}.</p>`;
}

/** Replace the <!-- gen:NAME --> ... <!-- /gen:NAME --> blocks of privacy.html. */
export function renderPrivacy(html, cfg) {
  const blocks = { stats: statsBlock(cfg), form: formBlock(cfg), publisher: publisherBlock(cfg) };
  for (const [name, body] of Object.entries(blocks)) {
    const re = new RegExp(`<!-- gen:${name} -->[\\s\\S]*?<!-- /gen:${name} -->`);
    if (!re.test(html)) throw new Error(`privacy.html : bloc gen:${name} absent`);
    html = html.replace(re, () => `<!-- gen:${name} -->\n${body}${body ? "\n" : ""}  <!-- /gen:${name} -->`);
  }
  return html;
}
